steppingRunnerSource:
import {readFileSync, writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import {run, instance} from './step_workload.ts';
import {decide} from '/home/holo/line/tools/measure/engine_decision.ts';
const [candidate, output, base='baseline', n='8'] = process.argv.slice(2);
const rounds=Number(n), paths=[base,candidate].map(n=>`/tmp/engine-round7/${n}.wasm`);
const sha=b=>createHash('sha256').update(b).digest('hex');
const modules=paths.map(p=>new WebAssembly.Module(readFileSync(p)));
const verification=modules.map(m=>run(instance(m),'replay',true));
assert.deepEqual(verification[1],verification[0]);
const samples=[];
for(let round=-3;round<rounds;round++) {
 for(const arm of round%2===0?[0,1]:[1,0]) {
  globalThis.gc();
  const ex=instance(modules[arm]);
  const {stepMs,frames}=run(ex,'replay');
  if(round>=0)samples.push({round,arm,stepMs,frames,wasmBytes:ex.memory.buffer.byteLength});
 }
}
const decision=decide(Array.from({length:rounds},(_,round)=>({base:samples.find(s=>s.round===round&&s.arm===0).stepMs,candidate:samples.find(s=>s.round===round&&s.arm===1).stepMs})));
const result={description:'Exploratory post-registration stepping diagnostic, fixed alternating pairs after three warmups in one process. Not a promotion gate.',date:new Date().toISOString(),artifacts:paths.map(path=>({path,sha256:sha(readFileSync(path))})),instrumentSource:readFileSync('/tmp/engine-round7/step_workload.ts','utf8'),verification,samples,decision};
writeFileSync(output,JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(decision));

