import {run,instance,workloads} from '/home/holo/line/tools/measure/engine_workload.ts';
const [out,...arms]=process.argv.slice(2),samples=[],artifacts=[];
for(const arm of arms){
 const bytes=readFileSync(`/tmp/engine-round7/${arm}.wasm`);artifacts.push({arm,sha256:createHash('sha256').update(bytes).digest('hex')});
